    "unknowns_of_linear_equations": "Неизвестные системы линейных уравнений, до десяти: строка A для каждого уравнения и его правая часть в b. Уравнений столько, сколько строк, неизвестных — сколько столбцов. Если решений много — все они, x = p + t v; если нет ни одного — ближайшее, методом наименьших квадратов. Введите размер A, 3×3 или 3 2, до 10×10, и по числу в каждую ячейку или вставьте в одну ячейку всю матрицу, из таблицы или как [1 2; 3 4]; пустая ячейка — 0.",
