    "satellite_or_planet_going": "Спутник или планета, обращающаяся вокруг тела массой M и радиусом R, по третьему закону Кеплера: по высоте над поверхностью, по периоду или по наименьшей и наибольшей высоте для эллипса — размер орбиты, период и скорость, в перицентре и апоцентре по уравнению vis-viva; с рисунком. По умолчанию Земля, 5.972e24 kg и 6.371e6 m; Солнце — 1.989e30 kg и 6.957e8 m. Геостационарная орбита — 86164 s.",
