    "mass_on_slope_of": "Тело на склоне с углом θ и трением μ: его вес, сила реакции опоры, сила вдоль склона, трение и ускорение, а также скользит ли оно.",
    "masses_over_pulley": "Грузы на блоке",
    "two_masses_on_string": "Два груза на нити через блок, m<sub>1</sub> висит, а m<sub>2</sub> тоже висит, как в машине Атвуда, лежит на столе или на склоне с углом θ, с трением μ: их ускорение, куда они движутся, натяжение нити и удерживает ли их трение; с рисунком. С расстоянием d — какую скорость они наберут и сколько на это уйдёт времени. С массой блока, диска, он тоже вращается.",
