    "gravitation": "Гравитация",
    "pull_between_two_masses": "Притяжение между двумя массами на расстоянии r по закону Ньютона; а для первой, как для планеты, — ускорение свободного падения на r, скорость и период круговой орбиты, вторая космическая скорость и радиус, внутри которого она была бы чёрной дырой, — радиус Шварцшильда. Земля — 5.972e24 kg, её радиус 6.371e6 m; Солнце — 1.989e30 kg.",
    "spring_of_stiffness_k": "Пружина жёсткостью k, растянутая или сжатая на x, по закону Гука: её сила и запасённая энергия; с массой — период.",
    "drag_and_terminal_velocity": "Сопротивление и предельная скорость",
