    "thin_lens_or_mirror": "Тонкая линза или зеркало: введите два из фокусного расстояния f, расстояния до предмета и до изображения — третье будет вычислено; увеличение и изображение. f больше 0 для собирающей линзы или вогнутого зеркала; расстояние до изображения меньше 0 — мнимое изображение.",
    "lensmaker_s_equation": "Формула тонкой линзы",
    "thin_lens_of_index": "Тонкая линза с показателем преломления n и поверхностями радиусов R<sub>1</sub>, первой, на которую падает свет, и R<sub>2</sub>: её фокусное расстояние, оптическая сила в диоптриях и собирает она свет или рассеивает; с рисунком. Радиус больше 0, если его центр за поверхностью, так что двояковыпуклая линза имеет R<sub>1</sub> больше 0 и R<sub>2</sub> меньше; пусто — плоская поверхность. Стекло — около 1.5; в воде n<sub>m</sub> равен 1.333.",
