    "fluid_flowing_at_v": "Жидкость, текущая со скоростью v в трубе диаметром d: её число Рейнольдса и течёт ли она плавно слоями, ламинарно, или бурлит, турбулентно, профиль скорости поперёк трубы нарисован; на длине L потеря давления на трение по Дарси — Вейсбаху, f из уравнения Колбрука по шероховатости трубы ε, и мощность на перекачку. Вода при 20 °C, если не указано, 998 kg/m³ и μ 1.002e-3 Pa·s; воздух — 1.204 и 1.81e-5. Стальная труба имеет шероховатость около 0.045 mm, пластиковая — 0.0015.",
