    "f_ma_inclined_plane": "F = ma, наклонная плоскость с трением, грузы на блоке, столкновения, импульс, кинетическая и потенциальная энергия, работа и мощность, момент силы и рычаги, гравитация и радиус Шварцшильда, пружины, сопротивление и предельная скорость, закон Кулона, магнитная сила, поле провода, соленоида или витка и индукция.",
    "electronics": "Электроника",
    "resistor_colour_code_both": "Цветовая маркировка резисторов в обе стороны, коды SMD и EIA-96, элементы последовательно и параллельно, закон Ома, сопротивление провода и его AWG, делитель и Тевенин, мост Уитстона, резисторы для светодиодов, конденсаторы, RC и RL, фильтры первого и второго порядка, плоский конденсатор, трансформаторы и переменный ток, трёхфазная мощность, импеданс и резонанс R, L и C, стоимость электроэнергии, время работы батареи; диоды и выпрямители с пульсациями; транзисторы-ключи и со смещением, MOSFET, стабилитроны, LM317, ОУ и 555; dBm, dBV и dBµV и усиление в dB. Значение элемента как пишется: 4.7k, 4k7, 100n; резистор для покупки из ряда E12.",
    "v_f_standing_waves": "v = fλ, стоячие волны струн и труб, биения, линзы и зеркала, формула тонкой линзы, преломление и предельный угол, интерференция на двух щелях или решётке, одна щель и разрешение линзы, поляризация, эффект Доплера для звука и света, свет и фотоны и звук в децибелах.",
    "matter": "Вещество",
