    "modern": "Современная",
    "e_mc_binding_energy": "E = mc², энергия связи, Q-значение реакции, фотоэффект, длины волн де Бройля, принцип неопределённости, частица в ящике, комптоновское рассеяние, туннелирование, специальная теория относительности, линии водорода и орбиты Бора и радиоактивный распад.",
    "biology": "Биология",
    "genetics_from_punnett_squares": "Генетика, от решёток Пеннета до карт генов и генетического риска; ДНК и РНК, трансляция, выравнивание, с праймерами, гидами CRISPR и гелями; белки и ферменты; разведения, подсчёты и qPCR в лаборатории; клетки; здоровье; и экология и эволюция. Нажмите на число, чтобы вставить его.",
    "close_biology": "Закрыть биологию",
