    "punnett_squares_of_up": "Решётки Пеннета до шести генов с рисунком и для X; Харди — Вайнберг по p, по числам с χ²-тестом или по рецессивному признаку; χ² скрещивания; карты генов для двух или трёх генов с рисунком хромосомы; вероятности потомства; наследуемость по уравнению селекционера; эпистаз и какое соотношение подходит; генетический риск, семья нарисована как родословная; и группы крови.",
    "sequence_s_length_bases": "Длина последовательности, основания, GC вдоль неё и масса, с комплементарной и обратно-комплементарной; трансляция в шести рамках и открытые рамки считывания с рисунком; колесо кодонов; T<sub>m</sub> праймера по ближайшим соседям с рисунком плавления; ДНК и РНК по A<sub>260</sub> и их чистота; масса, моли и копии; лигирование, плазмида на рисунке; рестрикция на геле; копии ПЦР по циклам; выравнивания, глобальное и локальное, с точечной диаграммой; гиды CRISPR; мотивы по кодам IUPAC; праймеры для мутагенеза и сборки по Гибсону; и геномы и их копии.",
    "protein_s_mass_pi": "Масса белка, pI, заряд, экстинкция и гидропатичность с рисунком; двадцать аминокислот, титрование каждой на рисунке; концентрация белка по A<sub>280</sub> или калибровочной кривой; кинетика ферментов по V<sub>max</sub> и K<sub>m</sub> или подгонкой к точкам, с ингибиторами и графиком Лайнуивера — Бёрка; связывание по Хиллу; доза — ответ с подогнанной IC<sub>50</sub>; и таблица очистки.",
    "lab": "Лаборатория",
    "c_v_c_v": "C₁V₁ = C₂V₂ и серийные разведения с пробирками на рисунке; приготовление раствора по молярности, формуле, проценту или исходному раствору; подсчёт клеток; рост и удвоение и OD<sub>600</sub>; колонии и CFU/mL; RPM и g центрифуги; мастер-микс для ПЦР; qPCR по ΔΔCt и его калибровочная кривая; среднее ± 2 SE с планками погрешностей; R<sub>f</sub> хроматографии; микроскоп; размеры по гелю; эффективность трансформации; посев на планшеты; MOI; радиоизотопы; и буферы.",
    "water_potential_osmolarity_and": "Водный потенциал, осмолярность и тоничность, эритроцит на рисунке; отношение поверхности к объёму; Q₁₀; диффузия по Фику; мембранные потенциалы по Нернсту и по Гольдману; свободная энергия; сердечный выброс и артериальное давление с рисунком; и дыхание, его АТФ и дыхательный коэффициент.",
